#include "PhysicsWorld.h"
#include <iomanip>
#include <iostream>
int main(){PhysicsWorld w;w.Init();w.CreateStaticBox({0,-.5f,0},{10,.5f,10},0,0);auto b=w.CreateDynamicSphere({0,.5f,0},.5f,1,0,1);w.ApplyLinearAcceleration(b,{0,-9.81f,0},1.f/60);w.Step(1.f/60);w.SetLinearVelocity(b,{0,.1f,0});w.Step(.01f);auto a=w.CreateDynamicSphere({-1.5f,w.GetTransform(b).position.y,0},.5f,1,0,1);w.SetLinearVelocity(a,{10,.1f,0});w.Step(.1f);std::cout<<std::setprecision(17);auto p=w.GetTransform(a).position,q=w.GetTransform(b).position;std::cout<<"before_fall a="<<p.x<<","<<p.y<<","<<p.z<<" b="<<q.x<<","<<q.y<<","<<q.z<<" exact_axis_gap="<<double(q.x)-double(p.x)-1<<" touching_pairs="<<w.FindCollidingPairs().size()<<"\n";const double gap=double(p.y)-.5;std::cout<<"independent_e1_final_y="<<.5+(double(.02f)-gap)<<" expected_vy=1\n";for(auto h:{a,b})w.SetLinearVelocity(h,{5,-1,0});w.Step(.02f);for(auto h:{a,b}){auto r=w.GetTransform(h).position,v=w.GetLinearVelocity(h);std::cout<<"after "<<r.x<<","<<r.y<<","<<r.z<<" v="<<v.x<<","<<v.y<<","<<v.z<<"\n";}}
